// =====================================================
// Service Visit Web Form Script
// =====================================================

frappe.web_form.after_load = () => {

    hide_footer_and_login_items();
    prevent_name_auto_translate();
    setup_date_picker();
    setup_reference_image_upload();
    setup_country_code_fields();
    setup_cr_no_placeholder();

};


// =====================================================
// Hide Footer / Powered By
// =====================================================

function hide_footer_and_login_items() {
    $("footer").hide();
    $(".footer-bottom-line").hide();
}

// =====================================================
// CR Placeholder
// =====================================================
function setup_cr_no_placeholder() {

    let field = frappe.web_form.fields_dict.cr_no;

    if (field && field.$input) {
        field.$input.attr("placeholder", "eg: 12345-1");
    }
}

// =====================================================
// Prevent Browser / Google Translate for Name Fields
// =====================================================

function prevent_name_auto_translate() {

    ["customer_name", "first_name", "last_name"].forEach(function(fieldname) {

        let field = frappe.web_form.fields_dict[fieldname];

        if (field && field.$input) {
            field.$input.attr("translate", "no");
            field.$input.attr("autocomplete", "off");
            field.$input.addClass("notranslate");
        }

        if (field && field.$wrapper) {
            field.$wrapper.attr("translate", "no");
            field.$wrapper.addClass("notranslate");
        }
    });
}


// =====================================================
// Date Picker Settings
// =====================================================

function setup_date_picker() {

    let date_field = frappe.web_form.fields_dict.date;

    if (!date_field) return;

    let dp = date_field.datepicker;

    if (dp) {
        dp.update({
            minDate: new Date(),

            onRenderCell(date, cellType) {
                if (
                    cellType === "day" &&
                    date.getDay() === 5
                ) {
                    return {
                        disabled: true
                    };
                }
            }
        });
    }

    if (date_field.$input) {
        date_field.$input
            .attr("readonly", true)
            .css("cursor", "pointer");
    }
}


// =====================================================
// Reference Image Upload
// =====================================================

function setup_reference_image_upload() {

    frappe.web_form.set_value("reference_images_json", "");

    if (
        !frappe.web_form.fields_dict.reference_upload_html ||
        !frappe.web_form.fields_dict.reference_upload_html.$wrapper
    ) {
        return;
    }

    let upload_html = `
        <div style="margin-top:10px;">

            <input
                type="file"
                id="ws_reference_file_input"
                accept="image/*"
                multiple
                style="display:none;"
            >

            <button
                type="button"
                id="ws_upload_reference_files"
                style="
                    width:100%;
                    background:#fafafa;
                    border:2px dashed #d5d9e0;
                    border-radius:8px;
                    padding:14px;
                    color:#344054;
                    font-size:15px;
                    font-weight:600;
                    text-align:center;
                    transition:all .2s ease;
                ">
                📎 Add Reference Images
            </button>

            <div id="ws_reference_upload_preview"
                style="margin-top:12px; font-size:13px;">
            </div>

        </div>
    `;

    frappe.web_form.fields_dict.reference_upload_html.$wrapper.html(upload_html);

    $("#ws_upload_reference_files").on("click", function () {
        $("#ws_reference_file_input").click();
    });

    $("#ws_reference_file_input").on("change", function () {

        let files = this.files;

        if (!files || !files.length) {
            return;
        }

        $("#ws_upload_reference_files")
            .prop("disabled", true)
            .text("Uploading...");

        let total_files = files.length;
        let completed = 0;

        Array.from(files).forEach(function(file) {

            let form_data = new FormData();

            form_data.append("file", file);
            form_data.append("is_private", 0);
            form_data.append("folder", "Home/Attachments");

            $.ajax({
                url: "/api/method/upload_file",
                type: "POST",
                data: form_data,
                processData: false,
                contentType: false,
                headers: {
                    "X-Frappe-CSRF-Token": frappe.csrf_token
                },

                success: function(r) {

                    let file_doc = r.message;

                    let existing = frappe.web_form.get_value(
                        "reference_images_json"
                    );

                    let uploaded_files = [];

                    if (existing) {
                        try {
                            uploaded_files = JSON.parse(existing);
                        }
                        catch (e) {
                            uploaded_files = [];
                        }
                    }

                    uploaded_files.push(file_doc.name);

                    let raw_json = JSON.stringify(uploaded_files);

                    frappe.web_form.set_value(
                        "reference_images_json",
                        raw_json
                    );

                    frappe.web_form.doc.reference_images_json = raw_json;

                    $("#ws_reference_upload_preview").append(`
                        <div style="
                            padding:8px 10px;
                            margin-bottom:6px;
                            background:#F9FAFB;
                            border:1px solid #E5E7EB;
                            border-radius:8px;
                            color:#344054;
                            font-weight:600;
                        ">
                            ✅ ${file.name}
                        </div>
                    `);
                },

                error: function() {
                    frappe.msgprint(
                        "Could not upload " + file.name
                    );
                },

                complete: function() {

                    completed++;

                    if (completed >= total_files) {

                        $("#ws_upload_reference_files")
                            .prop("disabled", false)
                            .text("📎 Add Reference Images");
                    }
                }
            });
        });

        this.value = "";
    });
}


// =====================================================
// Country Code UI
// =====================================================

function setup_country_code_fields() {

    add_country_code_to_phone("mobile_number", "+973 Bahrain");
    add_country_code_to_phone("whatsapp_no", "+973 Bahrain");
}


function add_country_code_to_phone(fieldname, default_code) {

    let field = frappe.web_form.fields_dict[fieldname];

    if (!field || !field.$wrapper) return;

    let $input = field.$wrapper.find("input");

    if (!$input.length) return;

    if (field.$wrapper.find(".ws-country-code").length) return;

    let $select = $(`
        <select class="form-control ws-country-code">
            <option value="+973 Bahrain">🇧🇭 +973</option>
            <option value="+966 Saudi Arabia">🇸🇦 +966</option>
            <option value="+971 United Arab Emirates">🇦🇪 +971</option>
            <option value="+968 Oman">🇴🇲 +968</option>
            <option value="+965 Kuwait">🇰🇼 +965</option>
            <option value="+974 Qatar">🇶🇦 +974</option>
        </select>
    `);

    $select.val(default_code);

    if (fieldname === "mobile_number") {
        frappe.web_form.set_value("mobile_country_code", default_code);
    }

    if (fieldname === "whatsapp_no") {
        frappe.web_form.set_value("whatsapp_country_code", default_code);
    }

    $select.on("change", function() {

        let value = $(this).val();

        if (fieldname === "mobile_number") {
            frappe.web_form.set_value("mobile_country_code", value);
        }

        if (fieldname === "whatsapp_no") {
            frappe.web_form.set_value("whatsapp_country_code", value);
        }
    });

    $input.before($select);

    $input.parent().css({
        display: "flex",
        alignItems: "center",
        gap: "5px"
    });

    $select.css({
        width: "120px",
        minWidth: "120px",
        flexShrink: 0
    });

    $input.css({
        flex: 1,
        minWidth: 0
    });
    
    $input.on("input", function() {
        this.value = this.value.replace(/\D/g, "");
    });
    
}


// =====================================================
// Validation
// =====================================================

frappe.web_form.validate = () => {


    let missing = [];
    
    if (!frappe.web_form.get_value("type")) {
        missing.push("Type");
    }

    if (!frappe.web_form.get_value("customer_type")) {
        missing.push("Customer Type");
    }

    else if (frappe.web_form.get_value("customer_type") === "Company") {

        if (!frappe.web_form.get_value("cr_no")) {
            missing.push("CR No");
        }

        if (!frappe.web_form.get_value("customer_name")) {
            missing.push("Company Name");
        }

        if (!frappe.web_form.get_value("first_name")) {
            missing.push("Contact First Name");
        }

        if (!frappe.web_form.get_value("last_name")) {
            missing.push("Contact Last Name");
        }
    }

    else {

        if (!frappe.web_form.get_value("first_name")) {
            missing.push("First Name");
        }

        if (!frappe.web_form.get_value("last_name")) {
            missing.push("Last Name");
        }
    }

    // Reference Images Mandatory
    let reference_images_json = frappe.web_form.get_value(
        "reference_images_json"
    );

    let reference_files = [];

    if (reference_images_json) {
        try {
            reference_files = JSON.parse(reference_images_json);
        }
        catch (e) {
            reference_files = [];
        }
    }

    if (!reference_files.length) {
        missing.push("Reference Images");
    }

    if (!frappe.web_form.get_value("whatsapp_no")) {
        missing.push("Whatsapp No");
    }

    if (!frappe.web_form.get_value("date")) {
        missing.push("Date");
    }

    if (!frappe.web_form.get_value("time")) {
        missing.push("Time");
    }

    if (!frappe.web_form.get_value("city")) {
        missing.push("City");
    }

    if (!frappe.web_form.get_value("subject")) {
        missing.push("Subject");
    }


    // Phone Validation
    function get_digits(value) {
        return (value || "").replace(/\D/g, "");
    }
    
    function get_country_rule(country_code) {
    
        const rules = {
            "+973 Bahrain": {
                length: 8,
                label: "Bahrain"
            },
            "+966 Saudi Arabia": {
                length: 9,
                label: "Saudi Arabia"
            },
            "+971 United Arab Emirates": {
                length: 9,
                label: "United Arab Emirates"
            },
            "+968 Oman": {
                length: 8,
                label: "Oman"
            },
            "+965 Kuwait": {
                length: 8,
                label: "Kuwait"
            },
            "+974 Qatar": {
                length: 8,
                label: "Qatar"
            }
        };
    
        return rules[country_code] || rules["+973 Bahrain"];
    }
    
    function validate_phone_by_country(fieldname, label, country_fieldname) {
    
        let value = frappe.web_form.get_value(fieldname);
    
        if (!value) return;
    
        let digits = get_digits(value);
        let country_code = frappe.web_form.get_value(country_fieldname);
    
        let rule = get_country_rule(country_code);
    
        if (digits.length !== rule.length) {
            missing.push(
                `${label} must be exactly ${rule.length} digits for ${rule.label}`
            );
        }
    }
    
    validate_phone_by_country(
        "whatsapp_no",
        "WhatsApp No",
        "whatsapp_country_code"
    );
    
    validate_phone_by_country(
        "mobile_number",
        "Mobile Number",
        "mobile_country_code"
    );

    // Customer Name Must Be English
    function has_arabic(text) {
        return /[\u0600-\u06FF]/.test(text || "");
    }

    if (frappe.web_form.get_value("customer_type") === "Company") {

        if (has_arabic(frappe.web_form.get_value("customer_name"))) {
            missing.push("Company Name must be in English");
        }

    } else {

        if (
            has_arabic(frappe.web_form.get_value("first_name")) ||
            has_arabic(frappe.web_form.get_value("last_name"))
        ) {
            missing.push("First Name and Last Name must be in English");
        }
    }

    if (missing.length) {

        frappe.msgprint({
            title: __("Required Fields Missing"),
            indicator: "red",
            message:
                "Please complete the following fields:<br><br>" +
                missing.map(field => "• " + field).join("<br>")
        });

        return false;
    }

    return true;
};


// =====================================================
// Map Picker
// =====================================================

(function() {

    var map_initialized = false;

    function init_service_visit_map() {

        if (map_initialized) {
            return;
        }

        if (
            !frappe.web_form ||
            !frappe.web_form.fields_dict ||
            !frappe.web_form.fields_dict.map_html
        ) {
            setTimeout(init_service_visit_map, 300);
            return;
        }

        map_initialized = true;

        frappe.require("/assets/worldshading/js/service_visit_location_picker.js", function() {
            frappe.call({
                method: "worldshading.api.maps.get_maps_key",
                callback: function(r) {
                    worldshading.service_visit_location_picker.init({
                        api_key: r.message,        // ← key fetched from server
                        require_location: true
                    });
                }
            });
        });

    }

    frappe.web_form.events.on("after_load", function() {
        init_service_visit_map();
    });

})();


